import json

W, H = 'white', 'black'

def sq2rc(s):
    return (8 - int(s[1]), ord(s[0]) - ord('a'))

def rc2sq(r, c):
    return chr(ord('a') + c) + str(8 - r)

PIECE_VALUE = {'p': 100, 'n': 320, 'b': 330, 'r': 500, 'q': 900, 'k': 0}

class Pos:
    def __init__(self, pieces, to_move, castle='', ep=None):
        self.bd = [['.'] * 8 for _ in range(8)]
        for s, p in pieces.items():
            r, c = sq2rc(s)
            self.bd[r][c] = p
        self.to_move = to_move
        self.castle = castle   # subset of 'KQkq'
        self.ep = ep
        self.hist = []

    def clone(self):
        p = Pos.__new__(Pos)
        p.bd = [row[:] for row in self.bd]
        p.to_move = self.to_move
        p.castle = self.castle
        p.ep = self.ep
        p.hist = []
        return p

    def piece_at(self, r, c):
        return self.bd[r][c]

    def find_king(self, color):
        k = 'K' if color == W else 'k'
        for r in range(8):
            for c in range(8):
                if self.bd[r][c] == k:
                    return (r, c)
        return None

    def color_of(self, ch):
        if ch == '.':
            return None
        return W if ch.isupper() else H

    def attacked(self, r, c, by):
        """Is square (r,c) attacked by side `by`?"""
        bd = self.bd
        # pawns: white pawns attack upward (r-1)
        if by == W:
            for dr, dc in ((-1, -1), (-1, 1)):
                rr, cc = r - dr, c - dc
                if 0 <= rr < 8 and 0 <= cc < 8 and bd[rr][cc] == 'P':
                    return True
        else:
            for dr, dc in ((1, -1), (1, 1)):
                rr, cc = r - dr, c - dc
                if 0 <= rr < 8 and 0 <= cc < 8 and bd[rr][cc] == 'p':
                    return True
        # knights
        for dr, dc in ((-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < 8 and 0 <= cc < 8:
                p = bd[rr][cc]
                if p != '.' and self.color_of(p) == by and p.lower() == 'n':
                    return True
        # king
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                rr, cc = r + dr, c + dc
                if 0 <= rr < 8 and 0 <= cc < 8:
                    p = bd[rr][cc]
                    if p != '.' and self.color_of(p) == by and p.lower() == 'k':
                        return True
        # sliding: rook/queen
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            rr, cc = r + dr, c + dc
            while 0 <= rr < 8 and 0 <= cc < 8:
                p = bd[rr][cc]
                if p != '.':
                    if self.color_of(p) == by and p.lower() in ('r', 'q'):
                        return True
                    break
                rr += dr
                cc += dc
        # sliding: bishop/queen
        for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
            rr, cc = r + dr, c + dc
            while 0 <= rr < 8 and 0 <= cc < 8:
                p = bd[rr][cc]
                if p != '.':
                    if self.color_of(p) == by and p.lower() in ('b', 'q'):
                        return True
                    break
                rr += dr
                cc += dc
        return False

    def in_check(self, color):
        k = self.find_king(color)
        if k is None:
            return False
        return self.attacked(k[0], k[1], H if color == W else W)

    def pseudo_moves(self, color):
        bd = self.bd
        out = []
        for r in range(8):
            for c in range(8):
                p = bd[r][c]
                if p == '.' or self.color_of(p) != color:
                    continue
                t = p.lower()
                if t == 'p':
                    d = -1 if color == W else 1
                    start = 6 if color == W else 1
                    promo_r = 0 if color == W else 7
                    # forward one
                    rr = r + d
                    if 0 <= rr < 8 and bd[rr][c] == '.':
                        if rr == promo_r:
                            for pr in 'qrbn':
                                out.append((r, c, rr, c, pr))
                        else:
                            out.append((r, c, rr, c, None))
                            # forward two
                            if r == start and bd[r + 2 * d][c] == '.':
                                out.append((r, c, r + 2 * d, c, None))
                    # captures
                    for dc in (-1, 1):
                        rr, cc = r + d, c + dc
                        if not (0 <= rr < 8 and 0 <= cc < 8):
                            continue
                        q = bd[rr][cc]
                        if q != '.' and self.color_of(q) != color:
                            if rr == promo_r:
                                for pr in 'qrbn':
                                    out.append((r, c, rr, cc, pr))
                            else:
                                out.append((r, c, rr, cc, None))
                        elif q == '.' and self.ep == (rr, cc):
                            out.append((r, c, rr, cc, 'ep'))
                elif t == 'n':
                    for dr, dc in ((-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)):
                        rr, cc = r + dr, c + dc
                        if 0 <= rr < 8 and 0 <= cc < 8:
                            q = bd[rr][cc]
                            if q == '.' or self.color_of(q) != color:
                                out.append((r, c, rr, cc, None))
                elif t == 'k':
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            rr, cc = r + dr, c + dc
                            if 0 <= rr < 8 and 0 <= cc < 8:
                                q = bd[rr][cc]
                                if q == '.' or self.color_of(q) != color:
                                    out.append((r, c, rr, cc, None))
                else:
