                            q = bd[rr][cc]
                            if q == '.':
                                out.append((r, c, rr, cc, None))
                            else:
                                if self.color_of(q) != color:
                                    out.append((r, c, rr, cc, None))
                                break
                            rr += dr
                            cc += dc
        # castling
        if color == W:
            if 'K' in self.castle and bd[7][4] == 'K' and bd[7][7] == 'R' and \
               bd[7][5] == '.' and bd[7][6] == '.' and \
               not self.attacked(7, 4, H) and not self.attacked(7, 5, H) and not self.attacked(7, 6, H):
                out.append((7, 4, 7, 6, 'castle'))
            if 'Q' in self.castle and bd[7][4] == 'K' and bd[7][0] == 'R' and \
               bd[7][1] == '.' and bd[7][2] == '.' and bd[7][3] == '.' and \
               not self.attacked(7, 4, H) and not self.attacked(7, 3, H) and not self.attacked(7, 2, H):
                out.append((7, 4, 7, 2, 'castle'))
        else:
            if 'k' in self.castle and bd[0][4] == 'k' and bd[0][7] == 'r' and \
               bd[0][5] == '.' and bd[0][6] == '.' and \
               not self.attacked(0, 4, W) and not self.attacked(0, 5, W) and not self.attacked(0, 6, W):
                out.append((0, 4, 0, 6, 'castle'))
            if 'q' in self.castle and bd[0][4] == 'k' and bd[0][0] == 'r' and \
               bd[0][1] == '.' and bd[0][2] == '.' and bd[0][3] == '.' and \
               not self.attacked(0, 4, W) and not self.attacked(0, 3, W) and not self.attacked(0, 2, W):
                out.append((0, 4, 0, 2, 'castle'))
        return out

    def make(self, mv):
        r, c, rr, cc, flag = mv
        bd = self.bd
        self.hist.append(([row[:] for row in bd], self.castle, self.ep, self.to_move))
        p = bd[r][c]
        bd[r][c] = '.'
        if flag == 'ep':
            bd[r][cc] = '.'
            bd[rr][cc] = 'P' if p == 'P' else 'p'
        elif flag == 'castle':
            bd[rr][cc] = p
            if cc == 6:
                bd[rr][5] = bd[rr][7]
                bd[rr][7] = '.'
            else:
                bd[rr][3] = bd[rr][0]
                bd[rr][0] = '.'
        else:
            if flag in ('q', 'r', 'b', 'n'):
                bd[rr][cc] = flag.upper() if p.isupper() else flag
            else:
                bd[rr][cc] = p
        # castling rights
        cs = self.castle
        if p == 'K':
            cs = cs.replace('K', '').replace('Q', '')
        if p == 'k':
            cs = cs.replace('k', '').replace('q', '')
        if (r, c) == (7, 0) or (rr, cc) == (7, 0):
            cs = cs.replace('Q', '')
        if (r, c) == (7, 7) or (rr, cc) == (7, 7):
            cs = cs.replace('K', '')
        if (r, c) == (0, 0) or (rr, cc) == (0, 0):
            cs = cs.replace('q', '')
        if (r, c) == (0, 7) or (rr, cc) == (0, 7):
            cs = cs.replace('k', '')
        self.castle = cs
        # ep square
        if p.lower() == 'p' and abs(rr - r) == 2:
            self.ep = ((r + rr) // 2, c)
        else:
            self.ep = None
        self.to_move = H if self.to_move == W else W

    def unmake(self):
        bd, cs, ep, tm = self.hist.pop()
        self.bd = bd
        self.castle = cs
        self.ep = ep
        self.to_move = tm

    def legal(self):
        color = self.to_move
        res = []
        for mv in self.pseudo_moves(color):
            self.make(mv)
            if not self.in_check(color):
                res.append(mv)
            self.unmake()
        return res

    def fen(self):
        rows = []
        for r in range(8):
            s = ''
            n = 0
            for c in range(8):
                p = self.bd[r][c]
                if p == '.':
                    n += 1
                else:
                    if n:
                        s += str(n)
                        n = 0
                    s += p
            if n:
                s += str(n)
            rows.append(s)
        ep = '-'
        if self.ep:
            ep = rc2sq(*self.ep)
        return '/'.join(rows) + ' ' + ('w' if self.to_move == W else 'b') + ' ' + \
               (self.castle or '-') + ' ' + ep + ' 0 1'


def mv_str(mv):
    r, c, rr, cc, flag = mv
    s = rc2sq(r, c) + rc2sq(rr, cc)
    if flag in ('q', 'r', 'b', 'n'):
        s += flag
    return s


def evaluate(pos):
    """Material + small mobility, from White's perspective."""
    sc = 0
    for r in range(8):
        for c in range(8):
            p = pos.bd[r][c]
            if p == '.':
                continue
            v = PIECE_VALUE[p.lower()]
            sc += v if p.isupper() else -v
    return sc


def search(pos, depth):
    """Alpha-beta, returns (score, best_moves list)."""
    color = pos.to_move
    best = None
    best_moves = []
    moves = pos.legal()
    if not moves:
        if pos.in_check(color):
            return (-100000 if color == W else 100000), []
        return 0, []
    if depth == 0:
        return evaluate(pos), [None]
    for mv in moves:
        pos.make(mv)
        if depth == 1:
            sc = evaluate(pos)
        else:
            sc, _ = search(pos, depth - 1)
        pos.unmake()
        if best is None or (color == W and sc > best) or (color == H and sc < best):
            best = sc
            best_moves = [mv]
        elif sc == best:
            best_moves.append(mv)
    return best, best_moves


def mate_in(pos, n, color):
    """Return list of moves that force mate in <= n plies (for side `color`)."""
    if pos.to_move != color:
        return []
    out = []
    for mv in pos.legal():
        pos.make(mv)
        if not pos.legal():
            if pos.in_check(pos.to_move):
                out.append(mv)
        elif n > 1:
            opp = pos.to_move
            allmate = True
            for omv in pos.legal():
                pos.make(omv)
                sub = mate_in(pos, n - 2, color) if n >= 2 else []
                pos.unmake()
                if not sub:
                    allmate = False
                    break
            if allmate:
                out.append(mv)
        pos.unmake()
    return out


if __name__ == '__main__':
    b = json.load(open('/app/board.json'))
    pos = Pos(b['pieces'], W, castle='', ep=None)
    print('FEN:', pos.fen())
    # legality
    assert pos.find_king(W) and pos.find_king(H), 'missing king'
    for r in range(8):
        for c in range(8):
            p = pos.bd[r][c]
            if p.lower() == 'p':
                assert r not in (0, 7), f'pawn on rank {8-r}'
    print('black in check now?', pos.in_check(H))
    moves = pos.legal()
    print('white legal moves:', len(moves))
    print('black in check after any white move?', end=' ')
    chk = []
    for mv in moves:
        pos.make(mv)
        if pos.in_check(H):
            chk.append(mv_str(mv))
        pos.unmake()
    print(chk)
    for d in (1, 2, 3):
        sc, best = search(pos, d)
        print(f'depth {d}: score={sc} best={[mv_str(m) for m in best][:12]}')
    for n in (1, 3):
        m = mate_in(pos, n, W)
        print(f'mate in {n} plies: {[mv_str(x) for x in m]}')
"}

