import struct
d=open('/app/alpine.iso','rb').read()
BS=2048
def read_dir(lba, length):
    data=d[lba*BS:lba*BS+length]
    off=0
    while off < len(data):
        L=data[off]
        if L==0:
            off=(off//BS+1)*BS
            if off>=len(data): break
            continue
        rec=data[off:off+L]
        elba=struct.unpack('<I',rec[2:6])[0]
        esize=struct.unpack('<I',rec[10:14])[0]
        flags=rec[25]; namelen=rec[32]; name=rec[33:33+namelen]
        if namelen==1 and name in (b'\x00',b'\x01'):
            off+=L; continue
        yield name.split(b';')[0].decode('latin1'), elba, esize, flags
        off+=L

def find(path):
    parts=[p for p in path.split('/') if p]
    lba, ln = 20, 2048
    for i,part in enumerate(parts):
        for nm,elba,esize,flags in read_dir(lba,ln):
            if nm.upper()==part.upper():
                if i==len(parts)-1 and not (flags&2):
                    return elba,esize
                lba,ln=elba,esize
                break
        else:
            return None
    return None

# list boot/syslinux
