import os,re
# find listening socket inode for port 6665
inode=None
for fn in ('/proc/net/tcp','/proc/net/tcp6'):
    for l in open(fn).read().splitlines()[1:]:
        f=l.split()
        if f[1].endswith(':1A09') and f[3]=='0A':
            inode=f[9]; print(fn,"LISTEN inode",inode)
if inode:
    for p in os.listdir('/proc'):
        if not p.isdigit(): continue
        fd=os.path.join('/proc',p,'fd')
        try: entries=os.listdir(fd)
        except Exception: continue
        for e in entries:
            try: t=os.readlink(os.path.join(fd,e))
            except Exception: continue
            if t=='socket:['+inode+']':
                try: cmd=open(os.path.join('/proc',p,'cmdline'),'rb').read().replace(b'\0',b' ').decode()[:120]
                except Exception: cmd='?'
                print("OWNER pid",p,cmd)
EOF

