  '2024-02-30', '2024-02-31', '2024-04-31', '2024-06-31',
  '2024-00-10', '2024-13-01', '2024-01-00', '2024-01-32',
  '2023-02-29',
]

def line_has_ipv4(line):
    return re.search(r'(?<![0-9A-Za-z])((25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])(\.(25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])){3})(?![0-9A-Za-z])', line) is not None

fails = []
line = '1.2.3.4 ' + ' '.join(valid + [b for b in bad])
# Each valid date alone should match last-date semantics
for d in valid:
    L = '1.2.3.4 at ' + d
    got = re.findall(p, L, re.MULTILINE)
    if got != [d]: fails.append(('valid', L, got))
for d in bad:
    L = '1.2.3.4 at ' + d
    got = re.findall(p, L, re.MULTILINE)
    if got != []: fails.append(('bad', L, got))

# no ipv4 -> no match
for d in valid:
    L = 'no ip here ' + d
    got = re.findall(p, L, re.MULTILINE)
    if re.findall(p, L, re.MULTILINE) : fails.append(('noip', L, got))

# last-date selection multiple valid
got = re.findall(p, '1.2.3.4 2024-01-01 2024-06-30 2024-12-31', re.MULTILINE)
if got != ['2024-12-31']: fails.append(('last', got))

# leading-zero octets should not match as IPv4
for txt in ['01.2.3.4 2024-01-15', '1.02.3.4 2024-01-15']:
    got = re.findall(p, txt, re.MULTILINE)
    if got: fails.append(('leadzero', txt, got))

# date glued to alphanumerics
for txt in ['x2024-01-15 1.2.3.4', '1.2.3.4 2024-01-15x']:
    got = re.findall(p, txt, re.MULTILINE)
    if got: fails.append(('glue', txt, got))

if fails:
    for f in fails: print('FAIL', f)
    print('FINAL CHECK FAILED')
else:
    print('FINAL CHECK PASSED')
